def rand_tree(rng, n, lo, hi, mode='rand'):
    V = [rng.randint(lo, hi) for _ in range(n)]
    L = [-1] * n
    R = [-1] * n
    if mode == 'rand':
        free = [(0, 0), (0, 1)]
        for v in range(1, n):
            k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            p, side = free.pop()
            if side == 0:
                L[p] = v
            else:
                R[p] = v
            free.append((v, 0))
            free.append((v, 1))
    elif mode == 'chain':
        for v in range(1, n):
            if rng.random() < 0.5:
                L[v - 1] = v
            else:
                R[v - 1] = v
    elif mode == 'complete':
        for v in range(1, n):
            p = (v - 1) // 2
            if v % 2:
                L[p] = v
            else:
                R[p] = v
    elif mode == 'caterpillar':
        m = (n + 1) // 2
        for i in range(1, m):
            L[i - 1] = i
            R[i - 1] = m + i - 1
    return ser(V, L, R)


